{"path": "/workspace/target/src/time_contract.py", "content": """"Serving time contract for green-taxi trip records.

TLC publishes pickup timestamps as *local wall clock* times for
America/New_York without an offset.  Production requests, however, may carry
an explicit UTC offset (or a trailing ``Z``), in which case the value
identifies a true instant and must be converted into New York local time
before any calendar part is derived.

Resulting ``time_quality`` values:

``wall``         naive local wall time that resolves to exactly one instant.
``instant``      offset-aware input, converted to America/New_York.
``ambiguous``    naive local time inside the repeated fall-back hour; the
                 instant (and therefore the local calendar part) cannot be
                 identified, so the parts are reported as ``UNKNOWN``.
``nonexistent``  naive local time inside the spring-forward gap; the wall time
                 never occurred, so parts are ``UNKNOWN``.
``invalid``      missing or unparseable timestamp; parts are ``UNKNOWN``.
"""

from __future__ import annotations

import datetime as _dt
import math

import pandas as pd

ZONE = "America/New_York"
UNKNOWN = "UNKNOWN"

COLUMNS = ["pickup_hour", "pickup_dayofweek", "time_quality"]

QUALITY_WALL = "wall"
QUALITY_INSTANT = "instant"
QUALITY_AMBIGUOUS = "ambiguous"
QUALITY_NONEXISTENT = "nonexistent"
QUALITY_INVALID = "invalid"


def _parse_one(value):
    """Return (timestamp, is_aware) or (None, False) when unusable."""
    if value is None:
        return None, False
    if isinstance(value, float) and math.isnan(value):
        return None, False
    if value is pd.NaT:
        return None, False
    if isinstance(value, (pd.Timestamp, _dt.datetime)):
        stamp = pd.Timestamp(value)
    elif isinstance(value, _dt.date):
        stamp = pd.Timestamp(value)
    else:
        text = str(value).strip()
        if not text or text.lower() in {"nan", "nat", "none", "null"}:
            return None, False
        try:
            stamp = pd.Timestamp(text)
        except Exception:
            try:
                stamp = pd.to_datetime(text, errors="coerce")
            except Exception:
                return None, False
    if stamp is pd.NaT or pd.isna(stamp):
        return None, False
    return stamp, stamp.tzinfo is not None


def _split(values: pd.Series):
    """Split a raw series into naive-wall and offset-aware components."""
    naive = {}
    aware = {}
    if pd.api.types.is_datetime64_any_dtype(values):
        tz = getattr(values.dtype, "tz", None)
        for key, stamp in values.items():
            if stamp is pd.NaT or pd.isna(stamp):
                continue
            if tz is None:
                naive[key] = pd.Timestamp(stamp)
            else:
                aware[key] = pd.Timestamp(stamp)
        return naive, aware

    for key, value in values.items():
        stamp, is_aware = _parse_one(value)
        if stamp is None:
            continue
        if is_aware:
            aware[key] = stamp
        else:
            naive[key] = stamp
    return naive, aware


def derive(values) -> pd.DataFrame:
    if not isinstance(values, pd.Series):
        values = pd.Series(list(values))

    index = values.index
    hour = pd.Series(UNKNOWN, index=index, dtype="object")
    dayofweek = pd.Series(UNKNOWN, index=index, dtype="object")
    quality = pd.Series(QUALITY_INVALID, index=index, dtype="object")

    naive, aware = _split(values)

    if aware:
        keys = list(aware.keys())
        stamps = pd.DatetimeIndex(
            [pd.Timestamp(aware[key]).tz_convert("UTC") for key in keys], tz="UTC"
        ).tz_convert(ZONE)
        hour.loc[keys] = [str(int(part)) for part in stamps.hour]
        dayofweek.loc[keys] = [str(int(part)) for part in stamps.dayofweek]
        quality.loc[keys] = QUALITY_INSTANT

    if naive:
        keys = list(naive.keys())
        wall = pd.DatetimeIndex([naive[key] for key in keys])
        standard = wall.tz_localize(ZONE, ambiguous=False, nonexistent="NaT")
        daylight = wall.tz_localize(ZONE, ambiguous=True, nonexistent="NaT")

        gap = standard.isna() | daylight.isna()
        repeated = (~gap) & (standard != daylight)
        good = (~gap) & (~repeated)

        hours = [str(int(part)) for part in wall.hour]
        dows = [str(int(part)) for part in wall.dayofweek]

        for position, key in enumerate(keys):
            if good[position]:
                hour.at[key] = hours[position]
                dayofweek.at[key] = dows[position]
                quality.at[key] = QUALITY_WALL
            elif repeated[position]:
                quality.at[key] = QUALITY_AMBIGUOUS
            else:
                quality.at[key] = QUALITY_NONEXISTENT

    return pd.DataFrame(
        {
            "pickup_hour": hour.astype(str),
            "pickup_dayofweek": dayofweek.astype(str),
            "time_quality": quality.astype(str),
        },
        index=index,
    )
"}

{"path": "/workspace/target/src/enrich.py", "content": """"Zone and rate-class enrichment for the serving path.

Production requests do not arrive with the tidy dtypes of the offline parquet
slice: identifier and code columns can be published (or serialized by an
upstream service) as 32/64-bit integers, floats, or whitespace padded strings
such as ``" 74.0 "``.  Every one of those spellings denotes the same
``LocationID``/``RatecodeID`` and must resolve through the shipped lookup
tables.

Resolution rules (the lookup tables and the data card are authoritative):

* An identifier is normalised to an integer regardless of how it was
  serialized.  Anything that does not denote an integer resolves to
  ``UNKNOWN``.
* Every ``LocationID`` published in ``taxi_zone_lookup.csv`` resolves through
  its own row -- including the special rows 264/265.  A blank ``Borough`` or
  ``service_zone`` falls back to that row's ``Zone`` label; if that is blank
  too, or the identifier is absent from the table, the value is ``UNKNOWN``.
* ``RatecodeID`` absent/missing means "rate not reported", which the codebook
  publishes as code 99 (``unknown_reported``/``unspecified``).  A code outside
  the codebook has no rate class and resolves to ``UNKNOWN``.
"""

from __future__ import annotations

import math

import numpy as np
import pandas as pd

UNKNOWN = "UNKNOWN"

ENRICHED_COLUMNS = ["pu_borough", "pu_service_zone", "do_borough",
                    "do_service_zone", "rate_class", "fare_basis"]

DEFAULT_RATE_CODE = 99

_MISSING_TEXT = {"", "nan", "none", "null", "na", "n/a", "nat", "-", "?", "unknown"}


def _to_int(value):
    """Best-effort integer identifier from any serialization; None if unusable."""
    if value is None or value is pd.NaT:
        return None
    if isinstance(value, (bool, np.bool_)):
        return None
    if isinstance(value, (int, np.integer)):
        return int(value)
    if isinstance(value, (float, np.floating)):
        if math.isnan(value) or math.isinf(value):
            return None
        if float(value).is_integer():
            return int(value)
        return None
    text = str(value).strip()
    if text.lower() in _MISSING_TEXT:
        return None
    try:
        number = float(text)
    except ValueError:
        return None
    if math.isnan(number) or math.isinf(number) or not number.is_integer():
        return None
    return int(number)


def _clean_label(value) -> str | None:
    """Normalise a lookup-table cell into a usable label, else None."""
    if value is None or value is pd.NaT:
        return None
    if isinstance(value, float) and math.isnan(value):
        return None
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    text = str(value).strip()
    if not text or text.lower() in {"nan", "none", "null"}:
        return None
    return text


def _zone_maps(zones: pd.DataFrame) -> tuple[dict, dict]:
    """Return {LocationID: borough} and {LocationID: service_zone} maps."""
    borough: dict[int, str] = {}
    service: dict[int, str] = {}
    for _, row in zones.iterrows():
        key = _to_int(row.get("LocationID"))
        if key is None:
            continue
        zone_label = _clean_label(row.get("Zone"))
        borough_label = _clean_label(row.get("Borough")) or zone_label
        service_label = _clean_label(row.get("service_zone")) or zone_label
        borough[key] = borough_label if borough_label is not None else UNKNOWN
        service[key] = service_label if service_label is not None else UNKNOWN
    return borough, service


def _rate_maps(rates: pd.DataFrame) -> tuple[dict, dict]:
    rate_class: dict[int, str] = {}
    fare_basis: dict[int, str] = {}
    for _, row in rates.iterrows():
        key = _to_int(row.get("code"))
        if key is None:
            continue
        rate_class[key] = _clean_label(row.get("rate_class")) or UNKNOWN
        fare_basis[key] = _clean_label(row.get("fare_basis")) or UNKNOWN
    return rate_class, fare_basis


def _column(trips: pd.DataFrame, *names: str) -> pd.Series:
    for name in names:
        if name in trips.columns:
            return trips[name]
    return pd.Series([None] * len(trips), index=trips.index, dtype="object")


def _resolve_zone(values: pd.Series, mapping: dict) -> pd.Series:
    resolved = []
    for value in values:
        key = _to_int(value)
        if key is None:
            resolved.append(UNKNOWN)
        else:
            resolved.append(mapping.get(key, UNKNOWN))
    return pd.Series(resolved, index=values.index, dtype="object")


def _resolve_rate(values: pd.Series, mapping: dict) -> pd.Series:
    resolved = []
    for value in values:
        key = _to_int(value)
        if key is None:
            # Rate not reported: the codebook publishes this as code 99.
            key = DEFAULT_RATE_CODE
        resolved.append(mapping.get(key, UNKNOWN))
    return pd.Series(resolved, index=values.index, dtype="object")


def enrich(trips: pd.DataFrame, zones: pd.DataFrame, rates: pd.DataFrame) -> pd.DataFrame:
    borough_map, service_map = _zone_maps(zones)
    rate_class_map, fare_basis_map = _rate_maps(rates)

    out = trips.copy()

    pu = _column(trips, "PULocationID", "pu_location_id", "pulocationid")
    do = _column(trips, "DOLocationID", "do_location_id", "dolocationid")
    rate = _column(trips, "RatecodeID", "ratecode_id", "ratecodeid", "RateCodeID")

    out["pu_borough"] = _resolve_zone(pu, borough_map).astype(str)
    out["pu_service_zone"] = _resolve_zone(pu, service_map).astype(str)
    out["do_borough"] = _resolve_zone(do, borough_map).astype(str)
    out["do_service_zone"] = _resolve_zone(do, service_map).astype(str)
    out["rate_class"] = _resolve_rate(rate, rate_class_map).astype(str)
    out["fare_basis"] = _resolve_rate(rate, fare_basis_map).astype(str)
    return out
"}

{"path": "/workspace/target/src/serve.py", "content": "from __future__ import annotations

from pathlib import Path

import pandas as pd

from . import enrich, features, model, time_contract

DATA = Path(__file__).resolve().parent.parent / "data"

# Columns the production serving contract is defined over.
CONTRACT_COLUMNS = list(features.CONTRACT_COLUMNS)


def load_reference() -> tuple[pd.DataFrame, pd.DataFrame]:
    zones = pd.read_csv(DATA / "taxi_zone_lookup.csv")
    rates = pd.read_csv(DATA / "rate_codes.csv")
    return zones, rates


def enrich_batch(trips: pd.DataFrame) -> pd.DataFrame:
    zones, rates = load_reference()
    enriched = enrich.enrich(trips, zones, rates)
    temporal = time_contract.derive(enriched["lpep_pickup_datetime"])
    for column in features.TIME_COLUMNS:
        enriched[column] = temporal[column].astype(str)
    return enriched


def contract_frame(trips: pd.DataFrame) -> pd.DataFrame:
    """Return exactly the contract columns for a batch of raw requests."""
    return enrich_batch(trips).loc[:, CONTRACT_COLUMNS].copy()


def build_matrix(trips: pd.DataFrame) -> pd.DataFrame:
    zones, rates = load_reference()
    return features.build(trips, zones, rates)


def score_batch(estimator, trips: pd.DataFrame) -> pd.Series:
    matrix = build_matrix(trips)
    return pd.Series(estimator.predict(matrix), name="predicted_duration_minutes")
"}

